def squash(s: str) -> str:
    out = []
    n = len(s)
    i = 0
    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1
        run_len = j - i
        esc = "\\" + c if ("0" <= c <= "9" or c == "\\") else c
        if run_len >= 3:
            out.append(f"{run_len}{esc}")
        else:
            out.append(esc * run_len)
        i = j
    return "".join(out)
